// Composio answers through MCP: a text block holding JSON, with one result per tool call.
function composio(json) {
  let r = json;
  if (r && Array.isArray(r.content)) {
    const block = r.content.find((c) => c && c.type === 'text');
    r = block ? block.text : undefined;
  }
  if (typeof r === 'string') r = JSON.parse(r);
  const results = (r && r.data && r.data.results) || (r && r.results) || [];
  const first = results[0];
  if (!first || !first.response || first.response.successful !== true) throw new Error('composio call failed');
  return first.response.data;
}// One job per meeting: Fireflies ids from the list, Gemini docs from Drive. A listing that
// failed becomes one failed job, so the summary reports it. Never an empty output: the loop
// must run so the webhook gets its answer.
const jobs = [];
const ff = $('List Fireflies').first().json;
const ffBody = ff.body !== undefined ? ff.body : ff;
const transcripts = ffBody && ffBody.data && Array.isArray(ffBody.data.transcripts) ? ffBody.data.transcripts : null;
if (ff.error !== undefined || ff.statusCode >= 400 || transcripts === null) {
  jobs.push({ failed: true, what: 'fireflies_list' });
} else {
  for (const t of transcripts) if (t && typeof t.id === 'string') jobs.push({ kind: 'fireflies', id: t.id });
}
try {
  const found = $('Find Gemini docs').first().json;
  if (found.error !== undefined) throw new Error('find failed');
  const files = composio(found).files || [];
  const seen = new Set();
  for (const f of files) {
    if (!f || typeof f.id !== 'string' || typeof f.name !== 'string') continue;
    // Gemini writes one doc per language for one meeting; the service dedupes them, so
    // export only the first and save a Composio call.
    const key = f.name.replace(/ \([^()]*\)$/, '');
    if (seen.has(key)) continue;
    seen.add(key);
    jobs.push({ kind: 'gemini', doc: { id: f.id, name: f.name, createdTime: f.createdTime } });
  }
} catch (e) {
  jobs.push({ failed: true, what: 'gemini_list' });
}
if (jobs.length === 0) jobs.push({ noop: true });
return jobs.map((json) => ({ json }));

// Fireflies transcript to a meeting body. The calendar window is the recording +/- 30 minutes.
const r = $input.first().json;
const body = r.body !== undefined ? r.body : r;
const t = body && body.data ? body.data.transcript : null;
if (r.error !== undefined || r.statusCode >= 400 || !t || typeof t.date !== 'number') {
  return [{ json: { failed: true, what: 'fireflies_fetch' } }];
}
const min = new Date(t.date - 30 * 60000).toISOString();
const max = new Date(t.date + (t.duration || 0) * 60000 + 30 * 60000).toISOString();
return [{ json: { body: { source: 'fireflies', transcript: t }, window: { min, max } } }];

