}// Composio returns the exported text as a short-lived download link.
const r = $input.first().json;
try {
  if (r.error !== undefined) throw new Error('export failed');
  const data = composio(r);
  const url = data && data.file && data.file.s3url;
  if (typeof url !== 'string' || !url.startsWith('https://')) throw new Error('no link');
  return [{ json: { url } }];
} catch (e) {
  return [{ json: { failed: true, what: 'gemini_export' } }];
}

// Exported doc to a meeting body. The service keeps the transcript part only. The doc is
// created when the meeting ends, so the window looks back 6 hours from that.
const job = $('Loop').first().json;
const r = $input.first().json;
if (r.failed || r.error !== undefined || typeof r.data !== 'string') {
  return [{ json: { failed: true, what: 'gemini_download' } }];
}
const created = Date.parse(job.doc.createdTime);
if (!Number.isFinite(created)) return [{ json: { failed: true, what: 'gemini_doc' } }];
const body = { source: 'gemini_doc', doc: { id: job.doc.id, name: job.doc.name, text: r.data }, created_time: new Date(created).toISOString() };
const window = { min: new Date(created - 6 * 3600000).toISOString(), max: new Date(created + 30 * 60000).toISOString() };
return [{ json: { body, window } }];

// Composio answers through MCP: a text block holding JSON, with one result per tool call.
function composio(json) {
  let r = json;
  if (r && Array.isArray(r.content)) {
    const block = r.content.find((c) => c && c.type === 'text');
    r = block ? block.text : undefined;
  }
  if (typeof r === 'string') r = JSON.parse(r);
  const results = (r && r.data && r.data.results) || (r && r.results) || [];
  const first = results[0];
  if (!first || !first.response || first.response.successful !== true) throw new Error('composio call failed');
  return first.response.data;
}// Adds the calendar events to the body. A failed calendar call fails the meeting instead of
// storing it with a wrong name: names are stable, and the next run tries again.
const job = $('Has body').first().json;
const r = $input.first().json;
try {
  if (r.error !== undefined) throw new Error('calendar failed');
  const items = composio(r).items || [];
  const calendarId = $('Settings').first().json.calendar_id;
  const events = items.slice(0, 50).map((e) => ({ ...e, title: e.summary, calendar_id: calendarId }));
  return [{ json: { post: { ...job.body, calendar_events: events } } }];
} catch (e) {
  return [{ json: { failed: true, what: 'calendar' } }];
}

// One answer for the whole run: stored and already stored paths, counts of skipped and failed,
// and for each failure the step where it stopped (a fixed name, never an error message).
const stored = [];
const already = [];
const failures = [];
let skipped = 0;
for (const { json } of $input.all()) {
  if (json.noop) continue;
  if (json.failed) { failures.push(typeof json.what === 'string' ? json.what : 'unknown'); continue; }
  const body = json.body || {};
  if (json.statusCode === 201 && typeof body.path === 'string') stored.push(body.path);
  else if (json.statusCode === 200 && body.already_stored && typeof body.path === 'string') already.push(body.path);
  else if (json.statusCode === 200 && body.skipped) skipped++;
  else failures.push(typeof json.statusCode === 'number' ? 'ingest_' + json.statusCode : 'ingest_unreachable');
}
return [{ json: { stored, already_stored: already, skipped, failed: failures.length, failures } }];
